namespace OrgCodeReviewCases.TC010;

using Microsoft.AspNetCore.Mvc;
public sealed record PaymentRequest(decimal Amount);
public interface IPaymentService { Task<object> PayAsync(PaymentRequest request, CancellationToken ct); }
public interface IIdempotencyService { Task ValidateAsync(string key, CancellationToken ct); }
[ApiController]
[Route("api/org/v{version:apiVersion}/payments")]
public sealed class PaymentsController : ControllerBase
{
    private readonly IPaymentService _payment; private readonly IIdempotencyService _idempotency;
    public PaymentsController(IPaymentService payment, IIdempotencyService idempotency) { _payment = payment; _idempotency = idempotency; }
    [HttpPost]
    public async Task<IActionResult> Pay(PaymentRequest request, CancellationToken ct)
    {
        var key = Request.Headers["X-Org-Idempotency-Key"].ToString();
        await _idempotency.ValidateAsync(key, ct);
        return Ok(await _payment.PayAsync(request, ct));
    }
}

